            0x00: 0x8000,  # TEMP
            0x01: 0x0220,  # CONFIG
            0x02: 0x6000,  # THIGH
            0x03: 0x8000,  # TLOW
            0x04: 0x0000,  # EEPROM_UL
            0x05: 0x0000,  # EEPROM1
            0x06: 0x0000,  # EEPROM2
            0x07: 0x0000,  # TEMP_OFFSET
            0x08: 0x0000,  # EEPROM3
            0x0F: 0x0117,  # DEVICE_ID
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        value = self.regs.get(addr, 0)
        if nbytes == 1:
            return (value >> 8) & 0xFF
        return value

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr in [0x00, 0x0F]:
            return  # TEMP and DEVICE_ID are read-only

        if nbytes == 1:
            current_value = self.regs.get(addr, 0)
            data = (data << 8) | (current_value & 0xFF)

        self.regs[addr] = data

        # Handle read-to-clear flags
        if addr == 0x01:
            self.regs[0x01] &= ~(1 << 15)  # CLEAR HIGH_ALERT
            self.regs[0x01] &= ~(1 << 14)  # CLEAR LOW_ALERT
            self.regs[0x01] &= ~(1 << 13)  # CLEAR DATA_READY

    def get_temperature(self) -> float:
        temp = self.regs[0x00]
        if temp & 0x8000:
            temp -= 0x10000
        return temp * 0.0078125  # Convert to Celsius

    def set_temperature(self, temp_celsius: float) -> None:
        temp = int(temp_celsius / 0.0078125)
        if temp < 0:
            temp += 0x10000
        self.regs[0x00] = temp

    def trigger_conversion(self) -> None:
        self.regs[0x01] |= (1 << 13)  # Set DATA_READY flag

