class TMP117_Simulator(BaseVirtualSensor):
    REG_WIDTH = 16

    def __init__(self):
        super().__init__()
        self.regs = {
            0x00: 0x8000,  # TEMP
            0x01: 0x0220,  # CONFIG
            0x02: 0x6000,  # THIGH
            0x03: 0x8000,  # TLOW
            0x04: 0x0000,  # EEPROM_UL
            0x05: 0x0000,  # EEPROM1
            0x06: 0x0000,  # EEPROM2
            0x07: 0x0000,  # TEMP_OFFSET
            0x08: 0x0000,  # EEPROM3
            0x0F: 0x0117,  # DEVICE_ID
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:#04x}")

        value = self.regs[addr]

        if nbytes == 1:
            value >>= 8

        return value & ((1 << (nbytes * 8)) - 1)

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:#04x}")

        if addr == 0x01:  # CONFIG
            current_value = self.regs[addr]
            if nbytes == 1:
                data <<= 8
            self.regs[addr] = (current_value & ~((1 << (nbytes * 8)) - 1)) | data
            self._clear_flags()
        elif addr == 0x04:  # EEPROM_UL
            self.regs[addr] = (data & 0x8000)  # Only EUN bit is writable
        else:
            pass  # Other registers are read-only

    def _clear_flags(self):
        config = self.regs[0x01]
        config &= ~(1 << 15)  # Clear HIGH_ALERT
        config &= ~(1 << 14)  # Clear LOW_ALERT
        config &= ~(1 << 13)  # Clear DATA_READY
        self.regs[0x01] = config
